package com.lqq.supportflow.knowledge.infrastructure.storage;
import com.lqq.supportflow.knowledge.domain.*; import java.io.*; import java.util.concurrent.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(prefix="supportflow.storage.minio",name="enabled",havingValue="false",matchIfMissing=true) public class InMemoryKnowledgeObjectStorage implements KnowledgeObjectStorage { private final ConcurrentMap<String,byte[]> objects=new ConcurrentHashMap<>(); public StoredKnowledgeObject put(Long tenantId,Long knowledgeBaseId,String contentHash,String fileName,String contentType,InputStream content,long size){try{String key="tenants/"+tenantId+"/knowledge-bases/"+knowledgeBaseId+"/"+contentHash;objects.putIfAbsent(key,content.readAllBytes());return new StoredKnowledgeObject(key,size,contentType);}catch(IOException exception){throw new IllegalArgumentException("cannot store document",exception);}} public InputStream open(String objectKey){byte[] value=objects.get(objectKey);if(value==null)throw new IllegalArgumentException("document object does not exist");return new ByteArrayInputStream(value);}}
